"use client";

import { useEffect, useRef, useState, type RefObject } from "react";
import { gsap, useGSAP } from "@/lib/gsap";
import { surahDataUrl } from "@/lib/surahs";

/** [Uthmani text, start ms, end ms] – generated by scripts/build-surah-data.mjs */
type Word = [text: string, start: number, end: number];
type Verse = {
  n: number;
  from: number;
  to: number;
  words: Word[];
  translation: string;
};
type SurahData = { number: number; audio: string; verses: Verse[] };

const cache = new Map<number, Promise<SurahData>>();
function loadSurah(n: number) {
  let p = cache.get(n);
  if (!p) {
    p = fetch(surahDataUrl(n)).then((r) => {
      if (!r.ok) throw new Error(`Surah ${n} data: ${r.status}`);
      return r.json() as Promise<SurahData>;
    });
    p.catch(() => cache.delete(n)); // allow a retry next time
    cache.set(n, p);
  }
  return p;
}

const AR_DIGITS = "٠١٢٣٤٥٦٧٨٩";
const toArabicDigits = (n: number) =>
  String(n).replace(/\d/g, (d) => AR_DIGITS[Number(d)]);

/** Index of the verse playing at `ms` (last verse that has started), or -1 before the first. */
function findVerse(verses: Verse[], ms: number) {
  let lo = 0;
  let hi = verses.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (verses[mid].from <= ms) {
      found = mid;
      lo = mid + 1;
    } else hi = mid - 1;
  }
  return found;
}

/**
 * Synced ayah display: the current verse's Arabic words light up as they're recited,
 * with the translation scrolling along underneath.
 */
export function AyahLyrics({
  surah,
  audioRef,
}: {
  surah: number | null;
  audioRef: RefObject<HTMLAudioElement | null>;
}) {
  const boxRef = useRef<HTMLDivElement>(null);
  const arabicRef = useRef<HTMLParagraphElement>(null);
  const transRef = useRef<HTMLParagraphElement>(null);
  const dataRef = useRef<SurahData | null>(null);
  const verseRef = useRef(-1);
  const wordRef = useRef(-2);

  const [data, setData] = useState<SurahData | null>(null);
  const [verseIdx, setVerseIdx] = useState(-1);
  const [failed, setFailed] = useState<number | null>(null);

  // Data for the current surah only; stale data from the previous surah is ignored.
  const active = data && data.number === surah ? data : null;
  const verse = active && verseIdx >= 0 ? active.verses[verseIdx] : undefined;

  useEffect(() => {
    if (surah === null) return;
    let alive = true;
    loadSurah(surah)
      .then((d) => alive && setData(d))
      .catch(() => alive && setFailed(surah));
    return () => {
      alive = false;
    };
  }, [surah]);

  useEffect(() => {
    dataRef.current = active;
    verseRef.current = -1;
  }, [active]);

  // Follow the audio every frame: switch verses, and light up the word being recited.
  useGSAP(() => {
    const tick = () => {
      const d = dataRef.current;
      const audio = audioRef.current;
      if (!d || !audio) return;
      const ms = audio.currentTime * 1000;

      const i = findVerse(d.verses, ms);
      if (i !== verseRef.current) {
        verseRef.current = i;
        wordRef.current = -2;
        setVerseIdx(i);
        return; // the new verse's words render first
      }
      if (i < 0) return;

      const v = d.verses[i];
      const arabic = arabicRef.current;
      if (arabic) {
        let w = -1;
        for (let k = 0; k < v.words.length && v.words[k][1] <= ms; k++) w = k;
        if (w !== wordRef.current) {
          wordRef.current = w;
          const spans = arabic.querySelectorAll<HTMLElement>("[data-word]");
          spans.forEach((el, k) => {
            el.dataset.state = k < w ? "past" : k === w ? "active" : "future";
          });
          // Long verses: scroll whole lines so the active word's line is the top visible one
          // (never stopping halfway through a line and slicing its diacritics).
          const cur = spans[w];
          if (cur && arabic.scrollHeight > arabic.clientHeight) {
            const lineH = parseFloat(getComputedStyle(arabic).lineHeight) || 48;
            const line = Math.floor(
              (cur.offsetTop + cur.offsetHeight / 2) / lineH,
            );
            const top = Math.min(
              line * lineH,
              arabic.scrollHeight - arabic.clientHeight,
            );
            if (Math.abs(arabic.scrollTop - top) > 1)
              arabic.scrollTo({ top, behavior: "smooth" });
          }
        }
      }
      // Translation scrolls along with the verse's progress.
      const trans = transRef.current;
      if (trans && trans.scrollHeight > trans.clientHeight) {
        const p = gsap.utils.clamp(
          0,
          1,
          (ms - v.from) / Math.max(1, v.to - v.from),
        );
        trans.scrollTop = (trans.scrollHeight - trans.clientHeight) * p;
      }
    };
    gsap.ticker.add(tick);
    return () => gsap.ticker.remove(tick);
  });

  // Open when a surah is in the player, close when it's ejected.
  useGSAP(
    () => {
      gsap.to(boxRef.current, {
        height: surah === null ? 0 : "auto",
        opacity: surah === null ? 0 : 1,
        duration: 0.6,
        ease: "power3.inOut",
      });
    },
    { dependencies: [surah === null] },
  );

  // Each new ayah rises in word by word, then its translation fades up.
  useGSAP(
    () => {
      if (!verse) return;
      const words = gsap.utils.toArray<HTMLElement>(
        "[data-word], [data-ayah-end]",
        boxRef.current,
      );
      gsap.from(words, {
        y: 14,
        opacity: 0,
        filter: "blur(6px)",
        duration: 0.55,
        ease: "power3.out",
        stagger: { amount: Math.min(0.6, words.length * 0.04) },
        clearProps: "transform,filter,opacity",
      });
      gsap.from(transRef.current, {
        y: 8,
        opacity: 0,
        duration: 0.6,
        delay: 0.15,
        ease: "power2.out",
      });
      arabicRef.current?.scrollTo({ top: 0 });
    },
    { dependencies: [surah, verse?.n], scope: boxRef },
  );

  return (
    <div ref={boxRef} className="h-0 overflow-hidden opacity-0" aria-live="off">
      <div className="mt-4 border-t border-zinc-200/80 pt-3 text-center">
        <p className="mb-1 text-[9px] font-medium tracking-[0.25em] text-zinc-400 uppercase">
          {verse ? `Ayah ${verse.n} of ${active!.verses.length}` : " "}
        </p>
        <p
          ref={arabicRef}
          lang="ar"
          dir="rtl"
          className="relative max-h-[96px] min-h-[48px] overflow-y-auto font-quran text-[20px] leading-[48px] [scrollbar-width:none] sm:text-[22px]"
        >
          {verse ? (
            <>
              {verse.words.map(([text], k) => (
                <span key={k}>
                  <span
                    data-word
                    data-state="future"
                    className="inline-block text-zinc-400 transition-[color,text-shadow,translate] duration-300 data-[state=active]:-translate-y-0.5 data-[state=active]:text-amber-600 data-[state=active]:[text-shadow:0_0_16px_rgba(251,191,36,0.6)] data-[state=past]:text-zinc-800"
                  >
                    {text}
                  </span>{" "}
                </span>
              ))}
              <span
                data-ayah-end
                className="inline-block text-[0.8em] text-amber-700/70"
              >
                ﴿{toArabicDigits(verse.n)}﴾
              </span>
            </>
          ) : (
            <span className="text-base text-zinc-400">
              {failed === surah ? "Couldn't load the ayah text" : " "}
            </span>
          )}
        </p>
        {/* <p
          ref={transRef}
          className="mt-1 max-h-[54px] min-h-[18px] overflow-hidden text-[11px] leading-[18px] text-zinc-800"
        >
          {verse?.translation ?? " "}
        </p> */}
      </div>
    </div>
  );
}
